mapper.select:
SELECT DISTINCT si.service_date
FROM erp_bookstore_slot_instance si
JOIN erp_bookstore_reservation r ON r.slot_instance_id = si.slot_instance_id
WHERE si.center_code = #{centerCode}
  AND si.service_date BETWEEN #{fromDate} AND #{toDate}
  AND r.status = 'RESERVED'

mapper.delete:
DELETE FROM erp_bookstore_slot_instance
WHERE center_code = #{centerCode}
  AND service_date = #{serviceDate}

  AND seq NOT IN
  #{s}

  AND NOT EXISTS (
      SELECT 1 FROM erp_bookstore_reservation r
      WHERE r.slot_instance_id = erp_bookstore_slot_instance.slot_instance_id
  )

mapper.update:
MERGE INTO erp_bookstore_slot_instance AS t USING (VALUES
(#{s.seq}, #{s.startsAt}, #{s.endsAt}, #{s.capacity}, #{s.status}, #{s.sourceType})
) AS src (seq, starts_at, ends_at, capacity, status, source_type) ON t.center_code = #{centerCode} AND t.service_date = #{serviceDate} AND t.seq = src.seq WHEN MATCHED THEN UPDATE SET t.starts_at = src.starts_at, t.ends_at = src.ends_at, t.capacity = src.capacity, t.status = src.status, t.source_type = src.source_type, t.materialized_at = DATEADD(HOUR, 9, GETUTCDATE()) WHEN NOT MATCHED BY TARGET THEN INSERT (center_code, service_date, seq, starts_at, ends_at, capacity, status, reserved_count, source_type, materialized_at) VALUES (#{centerCode}, #{serviceDate}, src.seq, src.starts_at, src.ends_at, src.capacity, src.status, 0, src.source_type, DATEADD(HOUR, 9, GETUTCDATE()));
